INSERT INTO v2_array_dwd_rebuild_20261123.dwd_stock_ccass_holding_detail_quarantine WITH version_flags AS (SELECT *,max(toUInt8(_observation_versions>1)) OVER (PARTITION BY `ts_code`,`trade_date`,`col_participant_id`) AS _key_conflict FROM (SELECT *,uniqExact(source_record_hash) OVER (PARTITION BY `ts_code`,`trade_date`,`col_participant_id`,sys_from) AS _observation_versions FROM v2_array_dwd_rebuild_20261123.dwd_stock_ccass_holding_detail_unresolved)) SELECT `trade_date`,`ts_code`,`name`,`col_participant_id`,`col_participant_name`,`col_shareholding`,`col_shareholding_percent`,`instrument_id`,`instrument_type`,`exchange`,`source_code`,`event_date`,CAST(NULL,'Nullable(Date32)'),`sys_from`,CAST(NULL,'Nullable(DateTime64(3))'),`source`,`source_table`,`source_batch_id`,`source_record_hash`,`availability_basis`,`shareholding`,`shareholding_percent`,'ambiguous_same_time_versions' FROM version_flags WHERE _key_conflict=1